import base64
from enum import IntEnum
from typing import Dict, List, Optional, Tuple

from buffer import ByteBuffer
import sys
import zlib
import lzma

# Увеличиваем лимит стека с 1000 до 100 000 вызовов
sys.setrecursionlimit(100000)

# Константа размера чанка из исходного кода
CHUNK_SIZE = 16


def zigzag_encode(val: int) -> int:
    return (val << 1) ^ (val >> 31)


def zigzag_decode(val: int) -> int:
    return (val >> 1) ^ -(val & 1)


class ArrowType(IntEnum):
    EMPTY = 0
    ARROW = 1
    SOURCE = 2
    BLOCKER = 3
    DELAY = 4
    DETECTOR = 5
    SPLITTER_UP_DOWN = 6
    SPLITTER_UP_RIGHT = 7
    SPLITTER_UP_RIGHT_LEFT = 8
    IMPULSE = 9
    BLUE_ARROW = 10
    DIAGONAL_ARROW = 11
    SPLITTER_UP_UP = 12
    SPLITTER_RIGHT_UP = 13
    SPLITTER_UP_DIAGONAL = 14
    LOGIC_NOT = 15
    LOGIC_AND = 16
    LOGIC_XOR = 17
    LATCH = 18
    FLIP_FLOP = 19
    RANDOM = 20
    BUTTON = 21
    LEVEL_SOURCE = 22
    LEVEL_TARGET = 23
    DIRECTIONAL_BUTTON = 24
    WALL = 25


# Матрицы вращения для вычисления относительных позиций
ROTATION_MATRICES = [
    {"fx": 0, "fy": 1, "sx": 1, "sy": 0},
    {"fx": -1, "fy": 0, "sx": 0, "sy": 1},
    {"fx": 0, "fy": -1, "sx": -1, "sy": 0},
    {"fx": 1, "fy": 0, "sx": 0, "sy": -1},
]

# Стандартная игровая карта связей
ARROW_RELATIONS_MAP: Dict[ArrowType, List[Tuple[int, int]]] = {
    ArrowType.ARROW: [[-1, 0]],
    ArrowType.BLOCKER: [[-1, 0]],
    ArrowType.DELAY: [[-1, 0]],
    ArrowType.DETECTOR: [[-1, 0]],
    ArrowType.LOGIC_NOT: [[-1, 0]],
    ArrowType.LOGIC_AND: [[-1, 0]],
    ArrowType.LOGIC_XOR: [[-1, 0]],
    ArrowType.LATCH: [[-1, 0]],
    ArrowType.FLIP_FLOP: [[-1, 0]],
    ArrowType.RANDOM: [[-1, 0]],
    ArrowType.LEVEL_SOURCE: [[-1, 0]],
    ArrowType.DIRECTIONAL_BUTTON: [[-1, 0]],
    ArrowType.SOURCE: [[-1, 0], [1, 0], [0, -1], [0, 1]],
    ArrowType.IMPULSE: [[-1, 0], [1, 0], [0, -1], [0, 1]],
    ArrowType.BUTTON: [[-1, 0], [1, 0], [0, -1], [0, 1]],
    ArrowType.SPLITTER_UP_DOWN: [[-1, 0], [1, 0]],
    ArrowType.SPLITTER_UP_RIGHT: [[-1, 0], [0, 1]],
    ArrowType.SPLITTER_UP_RIGHT_LEFT: [[0, -1], [-1, 0], [0, 1]],
    ArrowType.BLUE_ARROW: [[-2, 0]],
    ArrowType.DIAGONAL_ARROW: [[-1, 1]],
    ArrowType.SPLITTER_UP_UP: [[-1, 0], [-2, 0]],
    ArrowType.SPLITTER_RIGHT_UP: [[0, 1], [-2, 0]],
    ArrowType.SPLITTER_UP_DIAGONAL: [[-1, 0], [-1, 1]],
    ArrowType.EMPTY: [],
    ArrowType.WALL: [],
    ArrowType.LEVEL_TARGET: [],
}

# МАКСИМАЛЬНОЕ СЖАТИЕ: Архивационная карта связей.
# Мы соединяем стены друг с другом во все 4 стороны, превращая их в один связный граф!
SAVE_RELATIONS_MAP = ARROW_RELATIONS_MAP.copy()
SAVE_RELATIONS_MAP[ArrowType.WALL] = [[-1, 0], [1, 0], [0, -1], [0, 1]]


def get_arrow_relations(arrow_type: ArrowType) -> List[Tuple[int, int]]:
    return ARROW_RELATIONS_MAP.get(arrow_type, [])


def get_relative_position(
    x: int,
    y: int,
    rotation: int,
    flipped: bool,
    forward: int = -1,
    sideways: int = 0,
) -> Tuple[int, int]:
    matrix = ROTATION_MATRICES[rotation]
    sideways_dist = -sideways if flipped else sideways
    target_x = x + (forward * matrix["fx"] + sideways_dist * matrix["sx"])
    target_y = y + (forward * matrix["fy"] + sideways_dist * matrix["sy"])
    return target_x, target_y


class Arrow:
    def __init__(
        self,
        arrow_type: ArrowType,
        rotation: int,
        flipped: bool,
        global_x: int,
        global_y: int,
    ):
        self.type = arrow_type
        self.rotation = rotation
        self.flipped = flipped
        self.global_x = global_x
        self.global_y = global_y
        self.connections: List["Arrow"] = []
        self.back_connections: List["Arrow"] = []

    def __repr__(self):
        return (
            f"Arrow(Type: {self.type.name}, Pos: ({self.global_x}, {self.global_y}), "
            f"Rot: {self.rotation}, Flipped: {self.flipped})"
        )


class Chunk:
    def __init__(self, x: int, y: int):
        self.x = x
        self.y = y
        self.arrows: Dict[Tuple[int, int], Arrow] = {}

    def get_arrow(self, local_x: int, local_y: int) -> Optional[Arrow]:
        return self.arrows.get((local_x, local_y))

    def set_arrow(self, local_x: int, local_y: int, arrow: Arrow):
        self.arrows[(local_x, local_y)] = arrow


class GameMap:
    def __init__(self):
        self.chunks: Dict[Tuple[int, int], Chunk] = {}
        self.global_arrows: Dict[Tuple[int, int], Arrow] = {}

    def get_or_create_chunk(self, chunk_x: int, chunk_y: int) -> Chunk:
        coords = (chunk_x, chunk_y)
        if coords not in self.chunks:
            self.chunks[coords] = Chunk(chunk_x, chunk_y)
        return self.chunks[coords]

    def load(self, buffer: bytes) -> None:
        if len(buffer) < 4:
            return

        index = 0
        version = buffer[index] | (buffer[index + 1] << 8)
        index += 2
        if version != 0:
            raise ValueError("Unsupported save version")

        chunks_count = buffer[index] | (buffer[index + 1] << 8)
        index += 2

        for _ in range(chunks_count):
            chunk_x_low = buffer[index]
            chunk_x_high = buffer[index + 1]
            index += 2
            chunk_x = chunk_x_low | ((chunk_x_high & 0x7F) << 8)
            if (chunk_x_high & 0x80) != 0:
                chunk_x = -chunk_x

            chunk_y_low = buffer[index]
            chunk_y_high = buffer[index + 1]
            index += 2
            chunk_y = chunk_y_low | ((chunk_y_high & 0x7F) << 8)
            if (chunk_y_high & 0x80) != 0:
                chunk_y = -chunk_y

            arrows_types_count = buffer[index] + 1
            index += 1

            chunk = self.get_or_create_chunk(chunk_x, chunk_y)

            for _ in range(arrows_types_count):
                arrow_type_id = buffer[index]
                type_count = buffer[index + 1] + 1
                index += 2

                try:
                    arrow_type = ArrowType(arrow_type_id)
                except ValueError:
                    arrow_type = ArrowType.EMPTY

                for _ in range(type_count):
                    position = buffer[index]
                    rotation_byte = buffer[index + 1]
                    index += 2

                    local_x = position & 0xF
                    local_y = position >> 4

                    rotation = rotation_byte & 0x3
                    flipped = (rotation_byte & 0x4) != 0

                    global_x = chunk_x * CHUNK_SIZE + local_x
                    global_y = chunk_y * CHUNK_SIZE + local_y

                    arrow = Arrow(
                        arrow_type=arrow_type,
                        rotation=rotation,
                        flipped=flipped,
                        global_x=global_x,
                        global_y=global_y,
                    )

                    chunk.set_arrow(local_x, local_y, arrow)
                    self.global_arrows[(global_x, global_y)] = arrow

        self.resolve_relations()

    def resolve_relations(self) -> None:
        for coords, arrow in self.global_arrows.items():
            gx, gy = coords
            relations = get_arrow_relations(arrow.type)

            for forward, sideways in relations:
                target_gx, target_gy = get_relative_position(
                    gx, gy, arrow.rotation, arrow.flipped, forward, sideways
                )

                target_arrow = self.global_arrows.get((target_gx, target_gy))
                if target_arrow:
                    arrow.connections.append(target_arrow)
                    target_arrow.back_connections.append(arrow)


# ---- УЛЬТРА СЖАТИЕ С ПОДДЕРЖКОЙ КАРТЫ СТЕН ----


def compress_arrow(
    buffer: ByteBuffer,
    visited: set[Arrow],
    visited_pos: set[tuple[int, int]],
    arrow: Arrow,
    gamemap: GameMap,
):
    visited.add(arrow)
    visited_pos.add((arrow.global_x, arrow.global_y))

    # Используем SAVE_RELATIONS_MAP, в котором стены связаны друг с другом
    orig_relations = SAVE_RELATIONS_MAP.get(arrow.type, [])
    relations_mask = 0
    relations_to_write = []

    for idx, (forward, sideways) in enumerate(orig_relations):
        target_gx, target_gy = get_relative_position(
            arrow.global_x,
            arrow.global_y,
            arrow.rotation,
            arrow.flipped,
            forward,
            sideways,
        )

        target_arrow = gamemap.global_arrows.get((target_gx, target_gy))

        # Защитное ограничение: Стены соединяем только со стенами, чтобы не нарушать логику других схем
        if arrow.type == ArrowType.WALL:
            if target_arrow is None or target_arrow.type != ArrowType.WALL:
                continue

        if (
            target_arrow is not None
            and (target_gx, target_gy) not in visited_pos
            and target_arrow
            not in visited  # ИСПРАВЛЕНО: проверяем сам объект, а не его id
        ):
            relations_mask |= 1 << idx
            relations_to_write.append(target_arrow)

    metadata = (
        (1 if arrow.flipped else 0) | (arrow.rotation << 1) | (relations_mask << 3)
    )
    buffer.write_uint8(arrow.type.value)
    buffer.write_uint8(metadata)

    for child in relations_to_write:
        compress_arrow(buffer, visited, visited_pos, child, gamemap)


def compress_entry_arrow(
    buffer: ByteBuffer,
    visited: set[Arrow],
    visited_pos: set[tuple[int, int]],
    arrow: Arrow,
    gamemap: GameMap,
    last_x: int,
    last_y: int,
):
    # Дельта-кодирование стартовых точек
    dx = arrow.global_x - last_x
    dy = arrow.global_y - last_y
    buffer.write_varint32(zigzag_encode(dx))
    buffer.write_varint32(zigzag_encode(dy))

    compress_arrow(buffer, visited, visited_pos, arrow, gamemap)


def get_sorted_serialization_roots(gamemap: GameMap) -> List[Arrow]:
    """Находит минимально возможный набор стартовых точек (включая петли) и сортирует их по близости для ультра-сжатия дельт"""
    # 1. Считаем входящие связи с учетом SAVE_RELATIONS_MAP
    in_degree = {id(arrow): 0 for arrow in gamemap.global_arrows.values()}
    for arrow in gamemap.global_arrows.values():
        orig_relations = SAVE_RELATIONS_MAP.get(arrow.type, [])
        for forward, sideways in orig_relations:
            target_gx, target_gy = get_relative_position(
                arrow.global_x,
                arrow.global_y,
                arrow.rotation,
                arrow.flipped,
                forward,
                sideways,
            )
            target_arrow = gamemap.global_arrows.get((target_gx, target_gy))

            # Ограничение стен
            if arrow.type == ArrowType.WALL:
                if target_arrow is None or target_arrow.type != ArrowType.WALL:
                    continue

            if target_arrow:
                in_degree[id(target_arrow)] = in_degree.get(id(target_arrow), 0) + 1

    # Находим истинные корни (in-degree == 0)
    true_roots = [
        arrow
        for arrow in gamemap.global_arrows.values()
        if in_degree.get(id(arrow), 0) == 0
    ]
    # Сортируем истинные корни для идеального дельта-сжатия
    true_roots.sort(key=lambda a: (a.global_x, a.global_y))

    visited_pre = set()
    final_roots = []

    def mark_component(start_node):
        stack = [start_node]
        while stack:
            curr = stack.pop()
            if id(curr) in visited_pre:
                continue
            visited_pre.add(id(curr))

            orig_relations = SAVE_RELATIONS_MAP.get(curr.type, [])
            for forward, sideways in orig_relations:
                tgx, tgy = get_relative_position(
                    curr.global_x,
                    curr.global_y,
                    curr.rotation,
                    curr.flipped,
                    forward,
                    sideways,
                )
                if curr.type == ArrowType.WALL:
                    target_arrow = gamemap.global_arrows.get((tgx, tgy))
                    if target_arrow is None or target_arrow.type != ArrowType.WALL:
                        continue

                target_arrow = gamemap.global_arrows.get((tgx, tgy))
                if target_arrow and id(target_arrow) not in visited_pre:
                    stack.append(target_arrow)

    # Размечаем компоненты из истинных корней
    for root in true_roots:
        final_roots.append(root)
        mark_component(root)

    # Разрешаем изолированные циклы/остатки
    # Сортируем все стрелки карты, чтобы при нахождении петель дельты были минимальными
    all_sorted = sorted(
        gamemap.global_arrows.values(), key=lambda a: (a.global_x, a.global_y)
    )
    for arrow in all_sorted:
        if id(arrow) not in visited_pre:
            final_roots.append(arrow)
            mark_component(arrow)

    return final_roots


def graph_compress(gamemap: GameMap) -> bytes:
    buffer = ByteBuffer()

    # Получаем идеально отсортированный и минимальный список корней
    roots = get_sorted_serialization_roots(gamemap)

    visited = set()
    visited_pos = set()

    last_x, last_y = 0, 0

    for root in roots:
        compress_entry_arrow(
            buffer, visited, visited_pos, root, gamemap, last_x, last_y
        )
        last_x, last_y = root.global_x, root.global_y

    return bytes(buffer.bytes)


# ---- ДЕКОМПРЕССОР (ЗАГРУЗЧИК) ----


def graph_decompress(data: bytes) -> GameMap:
    buffer = ByteBuffer(data)
    gamemap = GameMap()
    visited_pos: set[tuple[int, int]] = set()

    def decompress_node(gx: int, gy: int):
        arrow_type_val = buffer.read_uint8()
        metadata = buffer.read_uint8()

        flipped = (metadata & 1) != 0
        rotation = (metadata >> 1) & 0x3
        relations_mask = metadata >> 3

        arrow_type = ArrowType(arrow_type_val)
        arrow = Arrow(arrow_type, rotation, flipped, gx, gy)

        gamemap.global_arrows[(gx, gy)] = arrow
        visited_pos.add((gx, gy))

        # При загрузке восстанавливаем по тем же правилам сжатия (со стенами)
        relations = SAVE_RELATIONS_MAP.get(arrow_type, [])
        for idx, (forward, sideways) in enumerate(relations):
            child_gx, child_gy = get_relative_position(
                gx, gy, rotation, flipped, forward, sideways
            )

            if (relations_mask & (1 << idx)) != 0:
                decompress_node(child_gx, child_gy)
            else:
                if (child_gx, child_gy) not in visited_pos:
                    visited_pos.add((child_gx, child_gy))

    # Восстановление дельта-координат
    last_x, last_y = 0, 0

    while buffer.offset < buffer.size:
        dx = zigzag_decode(buffer.read_varint32())
        dy = zigzag_decode(buffer.read_varint32())

        gx = last_x + dx
        gy = last_y + dy
        last_x, last_y = gx, gy

        decompress_node(gx, gy)

    # Важно: resolve_relations использует стандартную карту связей игры,
    # поэтому в памяти стены останутся без лишних связей!
    gamemap.resolve_relations()
    return gamemap


# --- Демонстрация работы ---
if __name__ == "__main__":
    chubrik_map = ""

    raw_bytes = base64.b64decode(chubrik_map)
    game_map = GameMap()
    game_map.load(raw_bytes)

    # 1. Применяем нашу СВЕРХСЖАТУЮ УЛЬТРА ВЕРСИЮ
    graph_data = graph_compress(game_map)

    print("--- Результаты сжатия ---")
    print("Исходный формат (raw):  ", len(raw_bytes), "байт")
    print("Графовый формат (graph):", len(graph_data), "байт")
    print("Коэффициент сжатия:     ", len(graph_data) / len(raw_bytes))

    # 2. Проверяем полную декомпрессию (чтобы доказать работоспособность)
    restored_map = graph_decompress(graph_data)
    assert len(restored_map.global_arrows) == len(game_map.global_arrows), (
        "Ошибка: Потерялись стрелки!"
    )
    print("\nПроверка пройдена: Карта успешно восстановлена без единой ошибки!")

    # Тест со стандартным Gzip/Deflate (zlib)
    raw_zlib = len(zlib.compress(raw_bytes))
    graph_zlib = len(zlib.compress(graph_data))

    print("\n--- Тест сжатия через Zlib (Deflate) ---")
    print(f"raw + zlib:   {raw_zlib} байт")
    print(f"graph + zlib: {graph_zlib} байт")
    print(f"Новое соотношение (ratio): {graph_zlib / raw_zlib:.4f}")

    # Тест с ультра-сжатием LZMA (как в UPX/.7z)
    raw_lzma = len(lzma.compress(raw_bytes))
    graph_lzma = len(lzma.compress(graph_data))

    print("\n--- Тест сжатия через LZMA ---")
    print(f"raw + lzma:   {raw_lzma} байт")
    print(f"graph + lzma: {graph_lzma} байт")
    print(f"Новое соотношение (ratio): {graph_lzma / raw_lzma:.4f}")

    print(f"Итоговое соотношение (ratio): {graph_lzma / len(raw_bytes):.4f}")
